{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 직원이 있는 공영주차장에 주차한 차량이 다른 차에 긁혀 가해자가 없을 때 주차장에 수리비 전액을 바로 청구할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "주차장의 관리자는 선량한 관리자의 주의의무를 다하여야 하고, 그 주의의무를 태만히 하지 아니하였음을 증명한 경우를 제외하고는 자동차의 훼손으로 인한 손해배상 책임을 면하지 못하므로, 직원이 상주하는 공영주차장에 주차한 차량이 긁힌 경우 주차장에 수리비 전액을 청구할 수 있습니다. 다만 관리자가 주의의무를 다하였음을 증명하면 책임을 면할 수 있으므로, 바로 전액 청구가 항상 인정되는 것은 아니고 관리자의 주의의무 위반 여부가 쟁점이 됩니다.",
          "b_ids": "주차장:제9조의2제1항, 주차장:제9조의2제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
